-- REQ: FR-RV-06 (observable state)

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity register_file is
    port(
        clk         : in std_logic;
        rst         : in std_logic;
        rs1_addr    : in std_logic_vector(4 downto 0);
        rs2_addr    : in std_logic_vector(4 downto 0);
        rd_addr     : in std_logic_vector(4 downto 0);
        rd_data_in  : in std_logic_vector(31 downto 0);
        rd_we       : in std_logic;
        rs1_data_out: out std_logic_vector(31 downto 0);
        rs2_data_out: out std_logic_vector(31 downto 0)
    );
end register_file;

architecture Behavioral of register_file is
    type reg_array_t is array (0 to 31) of std_logic_vector(31 downto 0);
    signal registers : reg_array_t := (others => (others => '0'));
begin

    -- Read operations are combinational
    rs1_data_out <= registers(to_integer(unsigned(rs1_addr))) when rs1_addr /= "00000" else (others => '0'); -- x0 is hardwired to 0
    rs2_data_out <= registers(to_integer(unsigned(rs2_addr))) when rs2_addr /= "00000" else (others => '0'); -- x0 is hardwired to 0

    -- Write operation with write-enable control
    process(clk, rst)
    begin
        if rst = '1' then
            registers <= (others => (others => '0'));
        elsif rising_edge(clk) and rd_we = '1' and rd_addr /= "00000" then -- x0 is hardwired to 0, no write allowed
            registers(to_integer(unsigned(rd_addr))) <= rd_data_in;
        end if;
    end process;

end Behavioral;
